package com.example.markdowndesk;

import java.io.*;
import java.nio.file.*;
import java.util.*;
import static com.example.markdowndesk.HistoryPinsCheck.*;

/** Production private sink and transitions; no fabricated copy proof or capture result. */
public final class PrivateArtifactCopyCheck {
    static int cases;
    interface Work{void run()throws Exception;}
    static void check(boolean ok,String why){if(!ok)throw new AssertionError(why);}
    static void reject(Work task,String why)throws Exception{try{task.run();throw new AssertionError("accepted "+why);}catch(IOException expected){}}
    static byte[] prefs(int theme)throws IOException{ByteArrayOutputStream b=new ByteArrayOutputStream();PrivateStateCodec.writePreferences(Collections.singletonMap("ui_theme",theme),b);return b.toByteArray();}
    static final class Capture {
        final Fixture f=new Fixture();final HistoryStorage.Budget budget=new HistoryStorage.Budget(HistoryStorage.METADATA_BUDGET);
        final UUID prep=UUID.randomUUID();final PreparationSources owner=PreparationSources.forPreparation(f.store.storageRoot(),prep,budget,PreparationSources.newProducer());
        final Disk disk=new Disk();final PrivateFramePreflight.Workspace copy;final PrivateCapturePlan plan;final PrivateCaptureWriter writer;
        final List<PrivateFramePreflight.ClosedFrame> frames=new ArrayList<>();
        Capture(boolean large)throws Exception{
            budget.charge(1L<<20);PrivateFramePreflight.Workspace preflight=PrivateFramePreflight.create(owner,budget);
            if(large){Path file=f.parent.resolve("source.frame");InputStream payload=new InputStream(){int left=PrivateStateCodec.MAX_PAYLOAD_BYTES;public int read(){if(left==0)return -1;left--;return 'x';}public int read(byte[] b,int o,int n){if(left==0)return -1;n=Math.min(n,left);Arrays.fill(b,o,o+n,(byte)'x');left-=n;return n;}};
                try(OutputStream out=Files.newOutputStream(file)){PrivateStateCodec.writeTab(new PrivateStateCodec.Tab("one","Large",new PrivateStateCodec.Provenance(null,null,-1,false),false,true,false,0,0,0,0,0,"","",false,false,false),PrivateStateCodec.MAX_PAYLOAD_BYTES,payload,out);}
                frames.add(preflight.attempt(PrivateStateCodec.Kind.SESSION_TAB,0,UUID.randomUUID(),UUID.randomUUID(),()->Files.newInputStream(file)).run());}
            byte[] p=prefs(8);frames.add(preflight.attempt(PrivateStateCodec.Kind.PREFERENCES,0,UUID.randomUUID(),UUID.randomUUID(),()->new ByteArrayInputStream(p)).run());
            copy=PrivateFramePreflight.create(owner,budget);final PrivateCapturePlan[] planned={null};final PrivateCaptureWriter[] published={null};
            locked(()->{HistoryControlStore.Inspection c=inspect(f);HistoryGraph.Graph g=new HistoryGraph(f.store,f.catalog,f.identity,f.index,null).scan();HistoryArchiveManifest m=HistoryArchiveManifest.freeze(g,c,UUID::randomUUID);PrivateOperationStore.Ledger l=PrivateOperationStore.inspect(f.store.storageRoot(),c,budget);
                planned[0]=PrivateCapturePlan.create(f.store.storageRoot(),f.catalog.storageRoot(),f.identity.storageRoot(),f.index.storageRoot(),m,g,c,l,owner,prep,UUID.randomUUID(),UUID.randomUUID(),UUID.randomUUID(),frames,64L<<20,budget);
                published[0]=PrivateCaptureWriter.prepareLocked(planned[0],f.store.storageRoot(),disk,budget);published[0].writeNativeLocked();});plan=planned[0];writer=published[0];
        }
        void locked(Work t)throws Exception{synchronized(HistoryStorage.monitorFor(f.store.storageRoot())){try(HistoryStorage.MutationScope lease=HistoryStorage.administration(f.store.storageRoot())){t.run();}}}
        Path target(int index){return f.parent.resolve("private_operations/"+prep+"/state-"+frames.get(index).artifactId+".frame");}
        void copyPreferences(InputStream input)throws IOException{writer.copyPrivate(frames.get(frames.size()-1),()->input,copy);}
    }
    static void normal()throws Exception {
        Capture c=new Capture(false);c.copyPreferences(new ByteArrayInputStream(prefs(8)));check(Files.isRegularFile(c.target(0)),"actual private stage promoted only after copy close");
        c.locked(()->{PrivateOperationStore.Ledger l=PrivateOperationStore.inspect(c.f.store.storageRoot(),inspect(c.f),c.budget);check(l.complete&&l.pending&&l.reservedBytes==0&&l.reservedEntries==0,"all native/private bytes consumed exact prior future credit");});
        reject(()->c.copyPreferences(new ByteArrayInputStream(prefs(8))),"same private artifact cannot be recopied");check(!Files.exists(c.f.parent.resolve("history_control/"+c.plan.prepare.begin.name())),"private copy grants no BEGIN");cases++;
    }
    static void changedAndSourceClose()throws Exception {
        Capture changed=new Capture(false);reject(()->changed.copyPreferences(new ByteArrayInputStream(prefs(7))),"changed valid regenerated bytes");check(!Files.exists(changed.target(0))&&Files.exists(changed.target(0).resolveSibling(changed.target(0).getFileName()+".stage")),"failed regenerated copy preserves stage without promotion");changed.writer.retryPrivateClose();cases++;
        for(boolean nativeFile:new boolean[]{false,true}){
            Capture c=new Capture(false);InputStream input=new ByteArrayInputStream(prefs(8)){public void close()throws IOException{
                Path target=nativeFile?c.f.parent.resolve("store/"+c.f.original.id+".snapshot"):c.target(0).resolveSibling(c.target(0).getFileName()+".stage");byte[] bytes=Files.readAllBytes(target);Path replacement=target.resolveSibling("replacement.tmp");Files.write(replacement,bytes);Files.move(replacement,target,StandardCopyOption.REPLACE_EXISTING);
            }};
            reject(()->c.copyPreferences(input),"same-byte replacement during source close "+nativeFile);check(!Files.exists(c.target(0)),"source-close callback cannot escape final physical recheck");cases++;
        }
    }
    static void closeFailureAndAuthority()throws Exception {
        for(boolean authority:new boolean[]{false,true}){
            Capture c=new Capture(false);int[] sourceCloses={0};boolean[] fired={false};c.disk.hook=(event,file)->{if(event.equals("file-after")&&!fired[0]){fired[0]=true;if(authority){try{HistoryCapacity.openLocked(c.f.store,c.f.catalog,c.f.identity,c.f.index,c.f.disk);}catch(IOException expected){}}else throw new IOException("private sink sync failure");}};
            InputStream input=new ByteArrayInputStream(prefs(8)){public void close(){sourceCloses[0]++;}};
            reject(()->c.copyPreferences(input),"private close callback failure/authority loss");check(fired[0]&&sourceCloses[0]==0,"failed sink closure keeps original source live");c.writer.retryPrivateClose();check(sourceCloses[0]==1&&!Files.exists(c.target(0)),"same retained handles cleanup under failed/frozen authority without promotion");cases++;
        }
    }
    static void representative()throws Exception {
        Capture c=new Capture(true);long start=System.nanoTime();c.writer.copyPrivate(c.frames.get(0),()->Files.newInputStream(c.f.parent.resolve("source.frame")),c.copy);long millis=(System.nanoTime()-start)/1000000;
        check(Files.size(c.target(0))==c.frames.get(0).envelopeBytes,"8MiB live-prefix copy exact final length");c.copyPreferences(new ByteArrayInputStream(prefs(8)));System.out.println("Representative single 8MiB private copy: "+millis+"ms (functional timing, not a benchmark budget)");cases++;
    }
    public static void main(String[] args)throws Exception{normal();changedAndSourceClose();closeFailureAndAuthority();representative();System.out.println("Actual private artifact copy: "+cases+" cases PASS");}
}
